declare(strict_types=1);require __DIR__.'/bootstrap.php';$key=(string)envv('CRON_KEY','');if($key===''||!hash_equals($key,(string)($_SERVER['HTTP_X_AMI_KEY']??$_REQUEST['key']??''))){http_response_code(403);exit('Forbidden');}$b=json_decode((string)file_get_contents('php://input'),true);if(!is_array($b))$b=$_POST+$_GET;
